WITH rebuilt AS (SELECT sm.id,jsonb_agg(e.value ORDER BY e.ordinality) FILTER (WHERE e.ordinality<>15) quiz FROM study_materials sm CROSS JOIN LATERAL jsonb_array_elements(sm.quiz) WITH ORDINALITY e(value,ordinality) WHERE sm.slug='contabilidade-gabriel-rabelo-fundamentos-classificacao-2026' GROUP BY sm.id) UPDATE study_materials sm SET quiz=r.quiz,updated_at=now() FROM rebuilt r WHERE sm.id=r.id AND jsonb_array_length(sm.quiz)=16 AND sm.quiz->12->>'q'=sm.quiz->14->>'q';